import{_ as a,c as e,o as t,af as r}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"卷五（序卦）","description":"伊川易传 - 卷五（序卦）","frontmatter":{"title":"卷五（序卦）","description":"伊川易传 - 卷五（序卦）"},"headers":[],"relativePath":"zh/classics/yichuan/006.md","filePath":"zh/classics/yichuan/006.md"}'),s={name:"zh/classics/yichuan/006.md"};function i(c,p,n,l,o,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<h1 id="卷五-序卦" tabindex="-1">卷五（序卦） <a class="header-anchor" href="#卷五-序卦" aria-label="Permalink to “卷五（序卦）”">​</a></h1><p>第一段</p><p>有天地，然后万物生焉。①盈天地之间者唯万物，故受之以屯。屯者，盈也。屯者，物之始生也。②物生必蒙，故受之以蒙。蒙者，蒙也，物之穉也。③物穉不可不养也，故受之以需。需者，饮食之道也。④饮食必有讼，故受之以讼。讼必有众起，故受之以师，师者，众也。⑤众必有所比，故受之以比。比者，比也。比必有所畜，故受之以小畜。⑥物畜然后有礼，故受之以履。履而泰然后安，故受之以泰。泰者，通也。⑦物不可以终通，故受之以否。物不可以终否，故受之以同人。⑧与人同者，物必归焉，故受之以大有。有大者不可以盈，故受之以谦。⑨有大而能谦必豫，故受之以豫。豫必有随，故受之以随。⑩以喜随人者必有事，故受之以蛊。蛊者，事也。⑾有事而后可大，故受之以临。临者，大也。物大然后可观，故受之以观。⑿可观而后有所合，故受之以噬嗑。嗑者，合也。物不可以苟合而已，故受之以贲。贲者，饰也。⒀致饰然后亨则尽矣，故受之以剥。剥者，剥也。物不可以终尽剥，穷上反下，故受之以复。⒁复则不妄矣，故受之以无妄。有无妄，然后可畜，故受之以大畜。⒂物畜然后可养，故受之以颐。颐者，养也。不养则不可动，故受之以大过。⒃物不可以终过，故受之以坎。坎者，陷也。陷必有所丽，故受之以离。离者，丽也。⒄</p><h3 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to “注释”">​</a></h3><p>①天地：此天地指六十四卦中的乾坤。以“天地”生万物说明乾坤为六十四卦之首的原因。万物：指自然界万物，此以“万物”说明六十四卦，“二篇之策万有一千五百二十，当万之数”。</p><p>②盈：满。受：继，承继。屯：卦名。屯本义从屮从一，屮即草，一为地，故有草木茁芽于地之义。《屯》卦下震上坎，坎为雨，震为雷，雷雨动荡，其气充塞。故屯为“盈”。又震为乾刚坤柔始交，故屯为“物之始生”。</p><p>③蒙：卦名。蒙本义是冢上草木，有覆盖之义。此通萌，郑玄曰：“齐人谓萌为蒙”，即指幼小之貌。物之初生幼小是未开著，故蒙为蒙昧。穉，一本作“稺”、“稚”。古三字通，有幼稚之义。</p><p>④需：卦名。通雩，本义指求雨之祭，引申为需求。《需》下乾上坎，坎为水，乾为天，云上于天，待时而落，故曰需有待、求雨之义。求雨为保丰年，而饮食有所依赖，故需又为“饮食之道”。</p><p>⑤讼：卦名。《讼》上乾为天，下坎为水，天在上，水在下，天与水违行，故有争讼之义。师：卦名。师为军旅之名，古二千五百人为师，师有众义。《师》下坎上坤，坤为众，坎为众。《国语·晋语》：“坎，劳也，水也，众也。”故师为众。</p><p>⑥比：卦名。一指周代社会基层组织，五家为比，比有亲密无间之义，《比》卦象是水在地上，有亲比之义。畜：一本作“蓄”，有畜养之义。小畜，为卦名。《小畜》＄一阴五阳，有一阴畜养五阳之义。阴为小，故曰小畜。</p><p>⑦履：卦名。履本指鞋，有践履之义，《履》卦上乾为天，下兑为泽，天高在上，泽卑在下，上下尊卑分明，故履为礼。《荀子》云：“礼者，人之所履也。”帛《易》履皆作“礼”。礼，指上下尊卑之等。李鼎祚《周易集解》、王弼《周易略例卦略》在“故受之以履”之后有“履者，礼也”。泰：卦名。帛《易》“泰”作“柰”。《泰》下乾上坤，乾阳下降，坤阴上升，故有阴阳交通之义，正如《彖》所言：“天地交而万物通也。”</p><p>⑧否：卦名。帛《易》“否”作“妇”，《否》与《泰》相反，《否》上乾为天，下坤为地，天地阴阳不交通，故否有不通之义。如《彖》所言：“天地不交而万物不通也。”同人：卦名。人即仁。同人即同仁，《同人》下离上乾，乾为天，离为火，天阳在上，离火炎上，故有志向相同之义。</p><p>⑨大有：卦名。古称丰年曰有，大丰年曰大有。《大有》一阴拥有五阳，大而富有，即《彖》所谓“柔得尊位，而上下应之，曰大有”。阳为大。谦：卦名。《谦》下艮上坤，艮山高而处地下，故有谦退之义。</p><p>⑩豫：卦名。豫本指象大，引申为娱乐，《豫》下坤上震，坤为地，震为雷，雷出地奋，万物顺性而动，故有喜乐之义。随：卦名。《随》下震上兑，震为雷在下，兑为泽在上，雷藏于泽中，随时休息，故有随从之义。</p><p>⑾蛊：卦名。蛊字本义为器皿食物腐败生虫，有败坏之义。《蛊》下巽上艮，艮为山，巽为风，风落山，其木摧坏，故有败坏之义。又艮为少男，巽为长女，有女惑男之象，万事从惑而起，故以蛊为事，蛊为事，盖假借“故”，非蛊字有“事”之训。王引之曰：“蛊之言，故也。《尚书大传》云：‘乃命五史。以书五帝之蛊事。’蛊事犹故事也。”</p><p>⑿临：卦名。帛易《临》卦作“林”，从爻画看《临》二刚临四柔，“刚浸而长”，故《临》刚有长大之义。观：卦名。《观》与《临》相反，《观》二阳在上，阳为大，故“物大然后可观”。</p><p>⒀噬嗑：卦名。噬嗑本义指嘴里有食物而咬合，《噬嗑》＄上下两阳，中一阳即是嘴里食物之象，此卦下震上离，离为电、震为雷、雷动而威，电闪而明，雷电相合，故有“合”之义。苟：但。《贲》：卦名。《贲》卦刚柔相错而文饰，故贲有饰之义。</p><p>⒁剥：卦名。剥有剥落之义。《剥》下坤上艮，艮为山，坤为地，山高反附于地故有剥落之义。又《剥》＄一阳于五阴之上，故有五阴剥落一阳之义。穷上反下：穷尽于上必复返于下。穷上，指《剥》一阳居上而穷尽。反下，指《复》卦一阳复一初爻。反，复。《复》＄一阳于五阴之下，有一阳复返之义。</p><p>⒂复则不妄：案《系辞》“复以自知”。自知而不妄，不妄即不妄行。《无妄》下震上乾，乾为天，震为雷，天下有雷动，故为不妄动。畜，本又作“蓄”，有积聚；蓄养之义。《大畜》下乾上艮，艮为山，乾为天，天在山中，天至大，山静止，山静止畜养至大，故为大畜。</p><p>⒃颐：原指人两腮。《颐》下震上艮，艮为止，震为动，上止下动。口腔之象，从卦画言《颐》＄上下二阳中四阴，外实中虚。像口腔，食物由口而入以养生，故颐有“养”之义。大过：指大的过失，《大过》下巽上兑，兑为泽，巽为木，泽灭木象故有过，从爻画看《大过》＄中四阳上下两阴，中间阳盛，上下弱，即本末弱，故为大过，阳为大。</p><p>⒄陷：通险。《坎》上下皆坎，坎阳陷于阴中故曰陷。丽：依附。《离》卦上下皆离，离阴依附于阳，故离为丽。</p><p>第二段</p><p>有天地然后有万物。有万物，然后有男女，有男女，然后有夫妇。有夫妇，然后有父子。有父子，然后有君臣。有君臣，然后有上下。有上下，然后礼仪有所错。①夫妇之道，不可以不久也，故受之以恒。恒者，久也。物不可以久居其所，故受之以遯。遯者，退也。②物不可以终遯，故受之以大壮。物不可以终壮，故受之以晋。晋者，进也。③进必有所伤，故受之以明夷。夷者，伤也。伤于外者必反一于家，故受之以家人。④家道穷必乖，故受之以睽。睽者，乖也。乖必有难，故受之以蹇。蹇者，难也。⑤物不可以终难，故受之以解。解者，缓也。缓必有所失，故受之以损，损而不已必益，故受之以益。⑥益而不已必决，故受之以夬。夬者，决也。决必有遇，故受之以姤。姤者，遇也。⑦物相遇而后聚，故受之以萃。萃者，聚也。聚而上者谓之升。故受之以升。⑧升而不已必困，故受之以困。困乎上者必反下，故受之以井。井道不可不革，故受之以革。⑨革物者莫若鼎，故受之以鼎。主器者莫若长子，故受之以震。震者，动也。⑩物不可以终动，止之，故受之以艮。艮者，止也。物不可以终止，故受之以渐。渐者，进也。进必有所归，故受之以归妹。⑾得其所归者必大，故受之以丰。丰者，大也。穷大者必失其居，故受之以旅。⑿旅而无所容，故受之以巽。巽者，入也。入而后说之，故受之以兑。兑者，说也。⒀说而后散之，故受之以涣。涣者，离也。物不可以终离，故受之以节，节而信之，故受之以中孚。⒁有其信者必行之，故受之以小过。有过物者必济，故受之以既济。物不可穷也，故受之以未济。终焉。⒂</p><h3 id="注释-1" tabindex="-1">注释 <a class="header-anchor" href="#注释-1" aria-label="Permalink to “注释”">​</a></h3><p>①此句就《咸》而言。《咸》下艮上兑，兑为少女，艮为少男，故称“男女”。《咸》“柔上而刚下，二气感应”，故有“夫妇”之象。艮兑为乾坤求索而生,故曰“父子”。乾坤有尊卑上下，故曰“君臣”“上下”。错。设置。</p><p>②恒：恒久。《恒》下巽上震，巽为风，震为雷，雷风相与而有恒久之义。遯：通“豚”，谓小猪。《周易》古经“遯”字皆为此义。而《易传》训遯为“退”。《遯》下艮上乾，艮为山，乾为天，山高上逼，天远山而退去，故遯为退，从爻画看，《遯》＄二阴在四阳之下，有渐长趋势，阳将退去，故曰退。</p><p>③大壮：此卦四阳盛长而壮大，故先儒多训壮为大。依《系辞》“日中则昃，月盈则食”之理，其《大壮》四阳盛长已过半，不久当止。故有止义。《杂卦》“大壮则止”是其确证。晋，有渐进之义。《晋》下坤上离，坤为地，离为日，日出地上，渐进上长，又从爻画看，“柔进而上行”，故晋有“进”义。</p><p>④明夷：有光明受伤之义。《明夷》与《晋》相反，《晋》是日出地上，《明夷》是日入地中，其光明受伤，故“明夷”有明伤之义。伤于外：《晋》离日在外，进极而伤入其内（变《明夷》）。反其家：《家人》离日在内。家人：指一家之人。《家人》下离上巽，离为火，巽为风，风火相与，有家人之义，又《家人》二五得正相应，二为女在内，五为男在外，男女正，故有家人之义。</p><p>⑤家道穷：指室家至亲，过而失节。乖：离散。睽：本义指目不相视，引申为乖异离散，《睽》下兑上离，离为火，兑为泽，火炎上，泽润下，二者相违背，故有“乖”之义。蹇：本指腿跛，行动不便，此引申为难，《蹇》下艮上坎，艮为山，坎为水，水为山所阻不得下流，故有“难”义。</p><p>⑥解：有缓解之义。《解》下坎上震，坎为雨，震为雷，雷震天上，雨落地下，故有缓解之义。损，减损。《损》下兑上艮，艮为山，兑为泽，泽深山高有损深而增高之义。从爻画看，《损》＄“损下益上”，故有减损之义。《益》与《损》相反，益，有增益之义，指上增益下，《益》下震上巽，巽为风，震为雷，雷风相与而增益，从爻画看，《益》＄“损上益下”，故有增益之义。</p><p>⑦决：溃决，决断。夬：朱骏声训本义为“＄”，“象环缺之形”。在《易传》，“夬”训之决。《夬》卦下乾上兑，乾为天，兑为泽，泽上于天，势必下流而散，有决之义，又从爻画看，《夬》＄一阴在五阳之上，有阳盛和决去一阴之象。决必有所遇：以阳决阴必有所喜遇。姤：相遇之义。《姤》下巽上乾，巽为风，乾为天，风行天下，无所不遇，故为遇，从爻画看，《姤》＄一阴在下与五阳相遇，故姤有“遇”之义。</p><p>⑧萃：会聚之义。《萃》下坤上兑，坤为地，兑为泽，泽在地上，聚水之象，从爻画看，《萃》九五居中得正，上下众阴皆应，故有聚会之义。聚而上者谓之升：是说反《萃》而成《升》，坤为众，《萃》卦坤众聚于下，《升》卦坤众在上，故曰“聚而上者谓之升”。聚，指坤众而言。升，有上升之义。《升》下巽上坤，巽为木，坤为地，地中生木，日长而升高，故有上升之义。</p><p>⑨困：穷困。《困》下坎上兑，坎为水，兑为泽，水在泽下，水下漏而上乾枯，故有穷困之义。困乎上者：指《困》卦水在泽下，泽上无水而穷困。必反下：反《困》成《井》，《困》兑泽到下，成巽木，而成《井》。故曰“反下”。井，有养之义。井道不可不革：即《系辞》所谓“居其所而迁”。即井能出水而利民，故曰“不可不革”。革，本指兽皮治去其毛此指变革。《革》卦下离上兑，兑为泽，离为火，泽火相息，故有变革之义。</p><p>⑩鼎：本指古代一种烹饪器和礼器，因鼎烹饪以成新物，故有取新之义。《杂卦》：“鼎，取新也。”故曰“革物莫若鼎”。《鼎》下巽上离，离为火，巽为木。木上有火，鼎烹饪之象。主器者：主管祭祀人。器，指鼎。主器者莫若长子：是指由长子主管祭祀。古代宗法世袭制度，王侯大夫之国与邑，原则上由长子继承，故长子掌管祭祀。震为长子。</p><p>⑾物不可终动：指反《震》成《艮》。屈万里《读易三种》：“岳珂九经三传沿革例，如《易序卦》‘不可以终动，动必止之’，诸本无‘动必，二字，惟蜀本；兴国本有之。”止，不动。《艮》上下皆艮，即上下不动，故曰止。渐，有渐进之义。《渐》下艮上巽，艮为山，巽木，为木生山上渐渐增高，故渐为“进”。进必有所归：指反《渐》成《归妹》。古代女子出嫁，按六礼进行，成婚过程称为渐，成婚为归妹。归，嫁。《归妹》下兑上震，震为长男，兑为少女，有少女归长男之象。</p><p>⑿丰：丰大之义。《丰》下离上震，震为雷，离为电，雷电至，威严而光明，丰有“大”义。旅：旅行。《旅》下艮上离，艮为山，离为火，山上有火，火行而不停。故有行之义。又内卦艮山静止为主，外卦火动为客，山不动如馆舍，火动不止如旅客，故旅有旅行之义。</p><p>⒀旅而无所容：旅客行动而无所容身。巽：帛《易》作“筭”，本指计算工具，此训为“入”，《巽》两巽相重，巽为风，风相随，风吹无所不入，故有“入”之义。兑：有欢悦之义，兑为口，故亦为“说”，通悦。</p><p>⒁涣：离散。《涣》下坎上巽，坎为水，巽为风，风行水上，将水冲散，故涣有“离”之义。离：散。节：节度。《节》卦下兑上坎，兑为泽，坎为水，泽上有水，其容量有限度，故节有节度之义。节而信之：节制而有诚信。中孚，中有孚信。《中孚》下兑上巽，巽为风，兑为泽，风令行于上，泽惠施于下，上下感应，有中孚之义。从爻画看，《中孚》＄上下二阳，中为二阴，内虚外实，心虚而有实，故为中孚。</p><p>⒂小过：小的经过。《小过》下艮上震，艮为山，震为雷，雷在山上，故有小过之象，从爻画看，《小过》上下各二阴，中间二阳，有二阴经过二阳之义。阴为小，故曰小过。此“过”不是过失而是经过。济：渡过，引申为成功。既济：指已成功。《既济》下离上坎，坎为水，离为火，水火相互交通，各得其用，故为“既济”之义。未济，未渡过，引申为未成功。《未济》与《既济》相反，为水火不相交，故有“未济”之义。</p>',39)])])}const f=a(s,[["render",i]]);export{d as __pageData,f as default};
